import{_ as n,c as t,o as r,ah as i}from"./chunks/framework.dGCgOE9J.js";const a="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_project_form.jpg",s="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_surface.jpg",o="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_conduit_type.jpg",l="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_microduct_colors.jpg",d="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_cable_type.jpg",h="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_component_structures.jpg",u="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_bulk_ports.jpg",m="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_container_types.jpg",b="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_company_form.jpg",S=JSON.parse('{"title":"21. Projekte und Stammdaten pflegen","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/21-projekte-und-stammdaten.md","filePath":"manual/teil-b-betrieb-admin-qgis/21-projekte-und-stammdaten.md"}'),c={name:"manual/teil-b-betrieb-admin-qgis/21-projekte-und-stammdaten.md"};function p(g,e,f,k,z,w){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_21-projekte-und-stammdaten-pflegen" tabindex="-1">21. Projekte und Stammdaten pflegen <a class="header-anchor" href="#_21-projekte-und-stammdaten-pflegen" aria-label="Permalink to &quot;21. Projekte und Stammdaten pflegen&quot;">​</a></h1><p>Projekte und Stammdaten legen Sie im Administrationsbereich an, siehe Kapitel <a href="./20-administrationsbereich.html">Der Administrationsbereich</a>. Die Weboberfläche liest sie nur: Ein Projekt, das hier fehlt, erscheint nicht in der Projektauswahl, ein Status, der hier fehlt, steht in keiner Auswahlliste. Was die einzelnen Listen für die Nutzenden bedeuten, beschreibt Abschnitt <a href="./../teil-a-anwenderhandbuch/02-grundbegriffe-und-datenmodell.html#_2-7-stammdaten-status-phase-netzebene-firmen">Stammdaten</a>.</p><p><img src="'+a+'" alt="Screenshot des Formulars eines Projekts im Administrationsbereich mit Name, Beschreibung und dem Schalter „Aktiv“ oben und den Projekteinstellungen darunter" data-zoomable="true"></p><p>Für alle Listen dieses Kapitels gilt:</p><ul><li>Stammdaten gelten für die ganze Installation, nicht je Projekt. Ein neuer Wert steht sofort in allen Projekten zur Auswahl.</li><li>Eine Umbenennung wirkt überall, wo der Wert verwendet wird. Ausnahmen sind die Farben, siehe Abschnitt <a href="#_21-4-rohrtypen-und-mikrorohrfarben">Rohrtypen und Mikrorohrfarben</a>.</li><li>Was beim Löschen eines Werts geschieht, der noch verwendet wird, hängt von der Liste ab: <ul><li><strong>Löschen samt Verwendung</strong> – „Rohrtypen“, „Kabeltypen“, „Komponententypen“, „Oberflächen“, „Bau-/Verlegearten“ und „Phasen“. Alle Objekte mit diesem Wert werden mitgelöscht, siehe unten.</li><li><strong>Löschen verweigert</strong> – „Mikrorohrfarben“ und „Faserfarben“, die ein Rohr- oder Kabeltyp verwendet, sowie „Faserstatus“, „Container-Typen“, „Wohnungseinheit-Typen“ und „Wohnungseinheit-Status“. Die Bestätigungsseite nennt die Objekte, die den Wert verwenden, und bietet keine Schaltfläche zum Bestätigen an.</li><li><strong>Fehler erst beim Löschen</strong> – „Netzebenen“, „Netzknotentypen“, „Gebietstypen“ und „Ausbaustatus“. Die Bestätigungsseite warnt nicht; erst das Löschen selbst scheitert mit einer Fehlerseite, und es wird nichts gelöscht.</li><li><strong>Mischfälle</strong> – „Status“, „Firmen“, „Kennzeichen“ und „Projekte“. Trassen mit diesem Wert werden mitgelöscht. Verwenden ihn auch Rohre, Netzknoten oder Kabel, scheitert das Löschen dagegen mit einer Fehlerseite, und es wird nichts gelöscht – auch keine Trasse. Verwenden Fasern das Kennzeichen oder das Projekt, verweigert schon die Bestätigungsseite das Löschen. Ein Projekt nimmt außerdem seine Einstellungen, Kostensätze, externen Kartendienste und Leitungsauskünfte mit.</li><li><strong>Wert wird entfernt</strong> – „Mikrorohrstatus“, „Art der Arbeiten“ und „Anfragegründe“. Die Objekte bleiben erhalten und verlieren nur diese Angabe.</li></ul></li></ul><p>Benennen Sie einen verwendeten Wert um, statt ihn zu löschen; wo es das Feld „Aktiv“ gibt, setzen Sie ihn auf inaktiv.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Ein gelöschter Rohrtyp nimmt alle Rohre dieses Typs mit, samt ihren Mikrorohren, ihrer Rohrzuordnung und den Verknüpfungen zu Kabeln. Ein gelöschter Kabeltyp nimmt alle Kabel dieses Typs mit, samt ihren Fasern und Spleißen, ein gelöschter Komponententyp alle eingebauten Komponenten mit ihren Spleißen. Eine gelöschte Oberfläche, Bauart oder Phase löscht alle Trassen, die sie verwenden, und mit ihnen deren Rohrzuordnung. Eine Fehlermeldung gibt es dabei nicht. Die Bestätigungsseite listet auf, was mitgelöscht wird – lesen Sie sie, bevor Sie bestätigen.</p></div><h2 id="_21-1-projekte-anlegen-und-vorbelegungen-setzen" tabindex="-1">21.1 Projekte anlegen und Vorbelegungen setzen <a class="header-anchor" href="#_21-1-projekte-anlegen-und-vorbelegungen-setzen" aria-label="Permalink to &quot;21.1 Projekte anlegen und Vorbelegungen setzen&quot;">​</a></h2><p>Projekte stehen unter „Api“ → „Projekte“. Ein Projekt hat einen Namen („Projekt“), eine „Beschreibung“ und den Schalter „Aktiv“. Nur aktive Projekte erscheinen in der Projektauswahl der Weboberfläche; ein inaktives Projekt behält seine Daten.</p><p>Unter den drei Feldern stehen die Einstellungen des Projekts: „Netzwerkschema“, „Rohrverzweigung“ und „Wertermittlungssätze“. Füllen Sie sie gleich beim Anlegen; was sie bewirken, beschreibt Kapitel <a href="./22-projektbezogene-konfiguration.html">Projektbezogene Konfiguration</a>.</p><p>Ohne Kostensätze lässt sich die Wertermittlung nicht benutzen. Ohne Netzschema- und Rohrabzweig-Einstellungen bieten Netzschema und Rohrverzweigung jeden Netzknoten des Projekts an.</p><p>Ein frisch eingerichtetes Qonnectra bringt das Projekt „Default“ und das Kennzeichen „Default“ mit, außerdem eine Grundausstattung an Stammdaten: Status, Oberflächen, Netzebenen, Netzknotentypen, Rohr- und Kabeltypen mit ihren Farben sowie je einen Eintrag für „Art der Arbeiten“ und „Anfragegründe“. Passen Sie diese Listen an, bevor die ersten Daten erfasst werden.</p><h2 id="_21-2-kennzeichen" tabindex="-1">21.2 Kennzeichen <a class="header-anchor" href="#_21-2-kennzeichen" aria-label="Permalink to &quot;21.2 Kennzeichen&quot;">​</a></h2><p>Kennzeichen stehen unter „Api“ → „Kennzeichen“. Ein Kennzeichen hat nur einen Namen. Was es in der Weboberfläche bewirkt, beschreibt Abschnitt <a href="./../teil-a-anwenderhandbuch/02-grundbegriffe-und-datenmodell.html#_2-6-kennzeichen-als-projektweiter-filter">Kennzeichen als projektweiter Filter</a>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Kennzeichen gehören keinem Projekt. Jedes Kennzeichen steht in allen Projekten zur Auswahl, auch wenn es nur in einem verwendet wird. Ein Name, aus dem das Projekt hervorgeht, hilft bei der Auswahl.</p></div><h2 id="_21-3-status-phase-netzebene-oberflache-bauart" tabindex="-1">21.3 Status, Phase, Netzebene, Oberfläche, Bauart <a class="header-anchor" href="#_21-3-status-phase-netzebene-oberflache-bauart" aria-label="Permalink to &quot;21.3 Status, Phase, Netzebene, Oberfläche, Bauart&quot;">​</a></h2><p>Diese Listen bestehen aus einem einzigen Feld, dem Namen des Werts. Sie stehen unter „Status“, „Phasen“, „Netzebenen“, „Oberflächen“ und „Bau-/Verlegearten“.</p><p>Die „Oberflächen“ haben zusätzlich das Feld „Versiegelung“, das festhält, ob die Oberfläche versiegelt ist. Es dient der Dokumentation; keine Auswertung rechnet damit, auch nicht die Wertermittlung, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/09-wertermittlung.html#_9-3-woher-die-kostensatze-kommen">Woher die Kostensätze kommen</a>.</p><p><img src="'+s+'" alt="Screenshot der Liste der Oberflächen mit Hervorhebung der Spalte „Versiegelung“ rechts" data-zoomable="true"></p><p>Nach demselben Muster gepflegt werden „Mikrorohrstatus“, „Faserstatus“ und „Ausbaustatus“ (für Adressen).</p><h2 id="_21-4-rohrtypen-und-mikrorohrfarben" tabindex="-1">21.4 Rohrtypen und Mikrorohrfarben <a class="header-anchor" href="#_21-4-rohrtypen-und-mikrorohrfarben" aria-label="Permalink to &quot;21.4 Rohrtypen und Mikrorohrfarben&quot;">​</a></h2><p>Ein <strong>Rohrtyp</strong> legt fest, welche Mikrorohre ein Rohr bekommt. Rohrtypen stehen unter „Rohrtypen“, ihre Felder:</p><ul><li>„Rohrtyp“ – der Name, etwa „12x10/6“.</li><li>„Rohrzahl“ – die Zahl der Mikrorohre, zur Information.</li><li>„Hersteller“ – eine Firma aus der Liste der Firmen.</li><li>Unter „Rohrtyp-Farbzuordnungen“ eine Zeile je Mikrorohr: „Position“ und „Farbe“.</li></ul><p><img src="'+o+'" alt="Screenshot des Formulars für einen Rohrtyp mit Hervorhebung der Farbzuordnungen" data-zoomable="true"></p><p>Die Mikrorohre eines neuen Rohrs entstehen aus den Farbzuordnungen, nicht aus der „Rohrzahl“: eines je Zeile, mit deren Position als Nummer und deren Farbe.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ein Rohrtyp ohne Farbzuordnungen erzeugt Rohre ohne Mikrorohre, ohne jede Meldung. Legen Sie die Zuordnungen an, bevor jemand den Typ verwendet. Rohre, die schon ohne Mikrorohre entstanden sind, ergänzt die Aktion „Mikrorohre für ausgewählte Rohre erstellen (nur wenn keine vorhanden sind)“, siehe Abschnitt <a href="./20-administrationsbereich.html#_20-2-suchen-filtern-und-massenbearbeitung">Suchen, Filtern und Massenbearbeitung</a>.</p></div><p>Die Zuordnungen wirken nur beim Anlegen eines Rohrs. Ändern Sie sie später, behalten bestehende Rohre ihre Mikrorohre, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/02-grundbegriffe-und-datenmodell.html#_2-1-trasse-rohr-und-mikrorohr">Trasse, Rohr und Mikrorohr</a>.</p><p>Die Farben selbst stehen unter „Mikrorohrfarben“. Jede Farbe hat die Felder „Deutscher Name“, „Englischer Name“, „Farbcode“ und, für zweifarbige Mikrorohre, „Sekundärer CSS-Farbcode“. „Anzeigereihenfolge“ und „Aktiv“ steuern die Auswahllisten.</p><p><img src="'+l+'" alt="Screenshot der Liste der Mikrorohrfarben mit Namen, Farbcodes und Anzeigereihenfolge in der Mitte" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Benennen Sie eine Farbe nicht um, die schon verwendet wird. Ein Mikrorohr speichert seine Farbe als Namen, nicht als Verweis. Nach der Umbenennung findet Qonnectra zu den bestehenden Mikrorohren keine Farbe mehr und zeichnet sie grau. Legen Sie stattdessen eine neue Farbe an und setzen Sie die alte auf inaktiv.</p></div><h2 id="_21-5-kabeltypen-faser-und-bundelfarben" tabindex="-1">21.5 Kabeltypen, Faser- und Bündelfarben <a class="header-anchor" href="#_21-5-kabeltypen-faser-und-bundelfarben" aria-label="Permalink to &quot;21.5 Kabeltypen, Faser- und Bündelfarben&quot;">​</a></h2><p>Ein <strong>Kabeltyp</strong> legt fest, welche Fasern ein Kabel bekommt. Kabeltypen stehen unter „Kabeltypen“, ihre Felder:</p><ul><li>„Kabeltyp“ – der Name.</li><li>„Faserzahl“ – die Zahl der Fasern, zur Information.</li><li>„Rohrzahl“ – trotz der Beschriftung die Zahl der <strong>Bündel</strong>.</li><li>„Faserzahl im Bündel“ – die Zahl der Fasern je Bündel.</li><li>„Hersteller“ – eine Firma aus der Liste der Firmen.</li><li>Unter „Faser-Farbzuordnungen“ je eine Zeile für jedes Bündel und für jede Faserposition im Bündel: „Positionstyp“ („Bündel“ oder „Faser“), „Position“, „Farbe“ und „Layer“ („Innen“ oder „Außen“).</li></ul><p><img src="'+d+'" alt="Screenshot des Formulars für einen Kabeltyp mit Hervorhebung der Felder für Bündel und Fasern und der Farbzuordnungen" data-zoomable="true"></p><p>Die Fasern eines neuen Kabels entstehen aus den Zuordnungen: für jedes Bündel so viele Fasern, wie „Faserzahl im Bündel“ angibt, mit der Bündelfarbe und der Farbe der Faserposition.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Fasern entstehen nur, wenn es mindestens so viele Bündel-Zeilen gibt, wie „Rohrzahl“ angibt, und mindestens so viele Faser-Zeilen, wie „Faserzahl im Bündel“ angibt. Fehlt auch nur eine, bleibt das neue Kabel ohne Fasern, ohne Meldung. Die Aktion „Fasern für ausgewählte Kabel erstellen (nur wenn keine vorhanden sind)“ ergänzt sie, sobald die Zuordnungen vollständig sind, siehe Abschnitt <a href="./20-administrationsbereich.html#_20-2-suchen-filtern-und-massenbearbeitung">Suchen, Filtern und Massenbearbeitung</a>.</p></div><p>Die Farben stehen unter „Faserfarben“ und werden wie die Mikrorohrfarben gepflegt; auch hier gilt die Warnung zur Umbenennung, siehe Abschnitt <a href="#_21-4-rohrtypen-und-mikrorohrfarben">Rohrtypen und Mikrorohrfarben</a>.</p><h2 id="_21-6-netzknotentypen-komponententypen-und-portdefinitionen" tabindex="-1">21.6 Netzknotentypen, Komponententypen und Portdefinitionen <a class="header-anchor" href="#_21-6-netzknotentypen-komponententypen-und-portdefinitionen" aria-label="Permalink to &quot;21.6 Netzknotentypen, Komponententypen und Portdefinitionen&quot;">​</a></h2><p><strong>Netzknotentypen</strong> stehen unter „Netzknotentypen“. Neben dem Namen haben sie die Felder „Dimension“, „Gruppe“ – ein Kürzel wie „HA“ oder „NVT“ – und „Firma“. Welche Netzknotentypen das Netzschema zeigt und welche als Rohrabzweig gelten, legen Sie je Projekt fest, siehe Kapitel <a href="./22-projektbezogene-konfiguration.html">Projektbezogene Konfiguration</a>.</p><p><strong>Komponententypen</strong> sind die Bauteile, die in die Slots eines Netzknotens eingesetzt werden, etwa eine Spleißkassette oder ein Splitter, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/02-grundbegriffe-und-datenmodell.html#_2-3-netzknoten-container-slots-komponenten-und-ports">Netzknoten, Container, Slots, Komponenten und Ports</a>. Sie stehen unter „Komponententypen“. „Belegte Steckplätze“ gibt an, wie viele Slots die Komponente einnimmt.</p><p>Die Ports eines Komponententyps stehen unter „Komponentenstrukturen“, eine Zeile je Port mit „In oder Out“, Portnummer und einem optionalen Alias. Ein Komponententyp ohne Ports lässt sich einsetzen, hat aber nichts, woran eine Faser anschließen kann.</p><p>Statt jeden Port einzeln anzulegen, nutzen Sie „Ports in Bulk erstellen“ oben rechts:</p><p><img src="'+h+'" alt="Screenshot der Komponentenstrukturen mit Hervorhebung des Filters nach Komponententyp rechts und der Schaltfläche „Ports in Bulk erstellen“ oben rechts" data-zoomable="true"></p><ol><li>Wählen Sie den „Komponententyp“.</li><li>Geben Sie die „Anzahl der Ports“ ein. Für jede Nummer entstehen ein Eingang und ein Ausgang; 12 ergibt 24 Einträge.</li><li>Lassen Sie die „Startposition“ auf 1, oder setzen Sie sie hinter die letzte vorhandene Nummer, um Ports zu ergänzen.</li><li>Klicken Sie auf „Ports erstellen“.</li></ol><p><img src="'+u+'" alt="Screenshot des Formulars „Ports in Bulk erstellen“ mit Komponententyp, Anzahl und Startposition oben im Inhaltsbereich" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Formular prüft nicht, ob es die Portnummern schon gibt. Ein zweiter Durchlauf mit derselben Startposition legt jeden Port doppelt an. Prüfen Sie vorher in der gefilterten Liste, bis zu welcher Nummer die Ports reichen.</p></div><h2 id="_21-7-container-typen" tabindex="-1">21.7 Container-Typen <a class="header-anchor" href="#_21-7-container-typen" aria-label="Permalink to &quot;21.7 Container-Typen&quot;">​</a></h2><p><strong>Container-Typen</strong> sind die Kategorien, mit denen sich Slot-Konfigurationen eines Netzknotens gruppieren lassen, etwa „Rack“ oder „Schrank“. Sie stehen unter „Container-Typen“. Eine neue Installation bringt keine mit; solange es keinen aktiven gibt, fehlt in der Weboberfläche die Schaltfläche „Container hinzufügen“, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/14-netzschema.html">Netzschema</a>.</p><p>In der Liste lassen sich „Anzeigereihenfolge“ und „Aktiv“ direkt ändern; speichern Sie mit „Sichern“ unter der Liste. Ein inaktiver Container-Typ verschwindet aus der Auswahl, bestehende Container behalten ihn.</p><p><img src="'+m+'" alt="Screenshot der Liste der Container-Typen mit Hervorhebung der direkt änderbaren Spalten „Anzeigereihenfolge“ und „Aktiv“" data-zoomable="true"></p><p>Im Formular eines Container-Typs stehen „Icon“, „Farbe“, „Anzeigereihenfolge“ und „Aktiv“ unter der Überschrift „Rohrverzweigung“. Die Überschrift ist ein Übersetzungsfehler; die Felder betreffen nur die Anzeige des Containers.</p><h2 id="_21-8-firmen-als-eigentumer-baufirma-und-hersteller" tabindex="-1">21.8 Firmen als Eigentümer, Baufirma und Hersteller <a class="header-anchor" href="#_21-8-firmen-als-eigentumer-baufirma-und-hersteller" aria-label="Permalink to &quot;21.8 Firmen als Eigentümer, Baufirma und Hersteller&quot;">​</a></h2><p>Firmen stehen unter „Firmen“. Dieselbe Liste speist die Felder „Eigentümer“, „Baufirma“ und „Hersteller“ der Fachobjekte und den „Hersteller“ der Rohr-, Kabel- und Komponententypen. Neben dem Namen („Firma“) hat eine Firma eine Anschrift, „Telefon“ und „E-Mail“.</p><p><img src="'+b+'" alt="Screenshot des Formulars „Firma hinzufügen“ mit Name, Stadt, Postleitzahl und Straße oben im Inhaltsbereich" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Weboberfläche zeigt von einer Firma nur den Namen. Anschrift, „Telefon“ und „E-Mail“ gibt Qonnectra über seine Schnittstelle aber an jedes angemeldete Konto heraus, siehe Kapitel <a href="./../teil-c-entwicklungs-systemdokumentation/32-rest-api.html">REST-API</a>. Tragen Sie dort nur Kontaktdaten ein, die alle Nutzenden sehen dürfen – eine allgemeine Rufnummer statt der Durchwahl einer Person.</p></div><h2 id="_21-9-gebietstypen" tabindex="-1">21.9 Gebietstypen <a class="header-anchor" href="#_21-9-gebietstypen" aria-label="Permalink to &quot;21.9 Gebietstypen&quot;">​</a></h2><p>Gebietstypen stehen unter „Gebietstypen“ und haben nur einen Namen, etwa „Projektgebiet“ oder „NVt-Gebiet“. Die Gebiete selbst zeichnen Sie in QGIS, siehe Kapitel <a href="./26-netzdaten-in-qgis-bearbeiten.html">Netzdaten in QGIS bearbeiten</a>. Wie ein Gebietstyp in der Karte aussieht, stellen die Nutzenden selbst ein, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/17-einstellungen.html">Einstellungen</a>.</p><h2 id="_21-10-adress-und-wohneinheitentypen" tabindex="-1">21.10 Adress- und Wohneinheitentypen <a class="header-anchor" href="#_21-10-adress-und-wohneinheitentypen" aria-label="Permalink to &quot;21.10 Adress- und Wohneinheitentypen&quot;">​</a></h2><p>Für Wohneinheiten gibt es zwei Listen, beide nur mit einem Namen: „Wohnungseinheit-Typen“, etwa Wohnung oder Gewerbe, und „Wohnungseinheit-Status“. Den Ausbaustatus einer Adresse pflegen Sie unter „Ausbaustatus“, siehe Abschnitt <a href="#_21-3-status-phase-netzebene-oberflache-bauart">Status, Phase, Netzebene, Oberfläche, Bauart</a>. Einen eigenen Typ für Adressen gibt es nicht.</p><h2 id="_21-11-nachschlagelisten-der-leitungsauskunft-art-der-arbeit-grund-der-anfrage" tabindex="-1">21.11 Nachschlagelisten der Leitungsauskunft: Art der Arbeit, Grund der Anfrage <a class="header-anchor" href="#_21-11-nachschlagelisten-der-leitungsauskunft-art-der-arbeit-grund-der-anfrage" aria-label="Permalink to &quot;21.11 Nachschlagelisten der Leitungsauskunft: Art der Arbeit, Grund der Anfrage&quot;">​</a></h2><p>Die Auswahllisten „Art der Arbeit“ und „Grund der Anfrage“ der Leitungsauskunft stehen unter „Art der Arbeiten“ und „Anfragegründe“, jeweils nur mit einem Namen. Mitgeliefert ist je ein Eintrag, „Straßenbau“ und „Baumaßnahme“. Beide Listen gelten für alle Projekte, siehe Kapitel <a href="./../teil-a-anwenderhandbuch/08-leitungsauskunft.html">Leitungsauskunft</a>.</p>',61)])])}const _=n(c,[["render",p]]);export{S as __pageData,_ as default};
